import type { SqlClient } from "./client";

/**
 * Transactional outbox for webhooks. Call `emitEvent` inside the same
 * transaction as the state change it describes: the `event` row and one
 * `webhook_delivery` row per subscribed, enabled endpoint commit (or roll
 * back) together with that change. The API worker delivers pending rows.
 */

export interface EmitEventInput {
  /** Event id (`evt_…`), generated by the caller with `newId("event")`. */
  id: string;
  /** Delivery id factory (`whd_…`), usually `() => newId("webhookDelivery")`. */
  deliveryId: () => string;
  orgId: string;
  type: string;
  data: Record<string, unknown>;
  at: Date;
}

export async function emitEvent(
  tx: SqlClient,
  input: EmitEventInput,
): Promise<{ eventId: string; deliveries: number }> {
  await tx.query("INSERT INTO event (id, org_id, type, payload, created_at) VALUES ($1, $2, $3, $4, $5)", [
    input.id,
    input.orgId,
    input.type,
    { id: input.id, type: input.type, created_at: input.at.toISOString(), data: input.data },
    input.at,
  ]);
  const { rows } = await tx.query<{ id: string }>(
    "SELECT id FROM webhook_endpoint WHERE org_id = $1 AND status = 'enabled' AND $2 = ANY(events)",
    [input.orgId, input.type],
  );
  for (const endpoint of rows) {
    await tx.query(
      "INSERT INTO webhook_delivery (id, endpoint_id, event_id, next_attempt_at, created_at, updated_at) VALUES ($1, $2, $3, $4, $4, $4)",
      [input.deliveryId(), endpoint.id, input.id, input.at],
    );
  }
  return { eventId: input.id, deliveries: rows.length };
}
